/* ---------- drawing helpers for this lesson (prefixed VL_ so they never clash with engine globals) ---------- */
const VL_F='font-family="Nunito Sans, sans-serif"';
const VL_GR='#5C6577', VL_LG='#ADB5BD';
const VL_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${VL_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}">${t}</text>`;
const VL_L=(x1,y1,x2,y2,col=VL_GR,w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const VL_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"/>`;
const VL_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=16;return VL_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const VL_poly=(pts,col,w=4,o={})=>`<polyline points="${pts.map(p=>p[0].toFixed(1)+','+p[1].toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${o.dash?'stroke-dasharray="9 7"':''}/>`;
/* computed curve: f(t) on t0..t1 drawn at x0..x1, y = Y(v) */
const VL_curve=(f,t0,t1,x0,x1,Y,col,w=4,o={},n=80)=>{const p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push([x0+(x1-x0)*i/n,Y(f(t))])}return VL_poly(p,col,w,o)};
/* horizontal MOS switch (channel left-right), centre x, channel at y; gate lead up to y-46; p: bubble on the gate */
const VL_mos=(x,y,col,p,lab='',gl=46)=>VL_L(x-30,y,x-30,y-12,col,3)+VL_L(x+30,y,x+30,y-12,col,3)+VL_L(x-36,y-12,x+36,y-12,col,4)+VL_L(x-30,y-21,x+30,y-21,col,3)+(p?`<circle cx="${x}" cy="${y-27}" r="6" fill="#FFFFFF" stroke="${col}" stroke-width="3"/>`+VL_L(x,y-33,x,y-gl,col,3):VL_L(x,y-21,x,y-gl,col,3))+(lab?VL_T(x,y-54,lab,{fs:22,fw:700,a:'middle',fill:col}):'');
/* vertical MOS (channel up-down) in a column at x, centre y; gate lead to the left (s=1) or right (s=-1) */
const VL_vmos=(x,y,col,p,s=1)=>{const c=x-14*s,gx=x-21*s;return VL_L(c,y-20,c,y+20,col,4)+VL_L(gx,y-16,gx,y+16,col,3)+`<polyline points="${c},${y-16} ${x},${y-16} ${x},${y-30}" fill="none" stroke="${col}" stroke-width="3"/>`+`<polyline points="${c},${y+16} ${x},${y+16} ${x},${y+30}" fill="none" stroke="${col}" stroke-width="3"/>`+(p?`<circle cx="${gx-6*s}" cy="${y}" r="5" fill="#FFFFFF" stroke="${col}" stroke-width="3"/>`:'')};
/* a 0 to VDD range bar: x from X0 to X1, passed range lo..hi in volts (VDD = 1.8 V) */
const VL_range=(y,lo,hi,col,lostLab,lostAt)=>{const X0=270,X1=600,X=v=>X0+(X1-X0)*v/1.8;let s=VL_L(X0,y+14,X1,y+14,VL_LG,2)+VL_L(X0,y+8,X0,y+20,VL_LG,2)+VL_L(X1,y+8,X1,y+20,VL_LG,2)+VL_T(X0,y+44,'0 V',{fs:22,a:'middle',fill:VL_GR})+VL_T(X1,y+44,'VDD',{fs:22,a:'middle',fill:VL_GR});
 s+=`<rect x="${X(lo).toFixed(1)}" y="${y-8}" width="${(X(hi)-X(lo)).toFixed(1)}" height="16" rx="8" fill="${col}"/>`;
 if(lostLab){const a=lostAt==='top'?X(hi):X0,b=lostAt==='top'?X1:X(lo);s+=`<rect x="${a.toFixed(1)}" y="${y-8}" width="${(b-a).toFixed(1)}" height="16" rx="8" fill="none" stroke="${TRED}" stroke-width="2" stroke-dasharray="6 5"/>`+VL_T((a+b)/2,y-18,lostLab,{fs:22,fw:700,a:'middle',fill:TRED})}
 return s};
/* a clean logic waveform from [x, level] pairs: level 0 or 1 between yLo and yHi */
const VL_wave=(pts,yLo,yHi,col,w=4,o={})=>VL_poly(pts.map(([x,l])=>[x,yLo+(yHi-yLo)*l]),col,w,o);
const VL_ground=(x,y,col=VL_GR)=>VL_L(x-14,y,x+14,y,col,3)+VL_L(x-9,y+6,x+9,y+6,col,3)+VL_L(x-4,y+12,x+4,y+12,col,3);
const VL_cap=(x,y,col=VL_GR)=>VL_L(x,y,x,y+14,col,3)+VL_L(x-16,y+14,x+16,y+14,col,4)+VL_L(x-16,y+22,x+16,y+22,col,4)+VL_L(x,y+22,x,y+34,col,3)+VL_ground(x,y+34,col);
const VL_inv=(x,y,col='#18213A')=>`<path d="M${x},${y-22} L${x+36},${y} L${x},${y+22} Z" fill="#FFFFFF" stroke="${col}" stroke-width="3"/><circle cx="${x+42}" cy="${y}" r="6" fill="#FFFFFF" stroke="${col}" stroke-width="3"/>`;
