function EXTRA(R,ICON){
 /* hook cards, 400 × 180, centred on x,y */
 const card=(x,y,col,lab,body)=>`<g transform="translate(${x-200} ${y-90})">${VL_box(0,0,400,180,{fill:'#FFFFFF',st:col,sw:3,r:18})}${VL_T(20,36,lab,{fs:24,fw:800,fill:col})}${body}</g>`;
 ICON.vlHookSwitch=(x,y)=>card(x,y,ORG,'pass switch: 1.8 V in',VL_T(24,112,'1.8 V',{fs:24,fw:800})+VL_L(96,104,150,104,VL_GR,3)+VL_L(210,104,262,104,VL_GR,3)+VL_mos(180,104,ORG,0)+VL_T(276,112,'1.10 V',{fs:24,fw:800,fill:ORG})+VL_T(200,160,'a weak 1 comes out',{fs:22,a:'middle',fill:VL_GR}));
 ICON.vlHookNode=(x,y)=>{const p=[[30,150],[60,150]];for(let i=0;i<=20;i++)p.push([60+i*6,150-80*(1-Math.exp(-i/4))]);p.push([200,70]);return card(x,y,BLU,'dynamic node: fill, then watch',VL_L(24,150,380,150,VL_LG,2)+VL_poly(p,BLU,5)+VL_poly([[200,70],[370,70]],VL_GR,3,{dash:1})+VL_curve(t=>Math.exp(-t),0,4,200,370,v=>150-80*v,ORG,4)+VL_T(372,62,'holds?',{fs:22,a:'end',fill:VL_GR})+VL_T(372,140,'drains?',{fs:22,a:'end',fill:ORG}))};
 /* recap pictures, about 420 × 330, centred on x,y */
 ICON.vlRcPass=(x,y)=>{const bar=(oy,lab,lo,hi,col,lost)=>{const X=v=>120+290*v/1.8;return VL_T(0,oy+10,lab,{fs:28,fw:800,fill:col})+`<rect x="120" y="${oy-22}" width="290" height="44" rx="22" fill="#F1F3F5"/>`+`<rect x="${X(lo).toFixed(1)}" y="${oy-22}" width="${(X(hi)-X(lo)).toFixed(1)}" height="44" rx="22" fill="${col}"/>`+VL_T(265,oy+52,lost,{fs:22,a:'middle',fill:VL_GR})};
  return `<g transform="translate(${x-210} ${y-165})">${bar(30,'nMOS',0,1.3,ORG,'weak 1')}${bar(140,'pMOS',0.5,1.8,BLU,'weak 0')}${bar(250,'TG',0,1.8,GRN,'0 V to VDD')}</g>`};
 ICON.vlRcDyn=(x,y)=>{const f=[[0,0]];for(let i=0;i<=20;i++)f.push([210+i*10,Math.exp(-i/4)]);
  return `<g transform="translate(${x-210} ${y-165})">${VL_T(0,58,'φ',{fs:26,fw:800,fill:BLU})}${VL_wave([[40,0],[200,0],[200,1],[420,1]],70,20,BLU)}${VL_T(0,178,'X',{fs:26,fw:800})}${VL_wave([[40,1],[205,1]].concat(f.slice(1)),180,120,ORG)}${VL_T(0,288,'out',{fs:26,fw:800,fill:GRN})}${VL_wave([[40,0],[205,0]].concat(f.slice(1).map(([a,l])=>[a,1-l])),300,240,GRN)}${VL_T(120,320,'precharge',{fs:22,a:'middle',fill:VL_GR})}${VL_T(320,320,'evaluate',{fs:22,a:'middle',fill:VL_GR})}</g>`};
 ICON.vlRcNums=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${VL_box(0,10,420,140,{st:BLU,sw:3})}${VL_T(210,62,'nMOS switch',{fs:24,fw:700,a:'middle',fill:BLU})}${VL_T(210,122,'1.8 V → 1.10 V',{fs:36,fw:800,a:'middle',fill:BLU})}${VL_box(0,175,420,140,{st:ORG,sw:3})}${VL_T(210,227,'charge sharing',{fs:24,fw:700,a:'middle',fill:ORG})}${VL_T(210,287,'1.8 V → 1.50 V',{fs:36,fw:800,a:'middle',fill:ORG})}</g>`;
}
